// Offline test of the script generated by scripts/apply-banner-css.py.
// It runs the generated dev-browser script against a fake browser, a fake WordPress Customizer and a
// fake front end, so the marker logic, idempotency and safety stops can be checked without a site.
// Usage: node tests/test_apply_banner_css.mjs   (run from the repository root)
import { execFileSync } from 'node:child_process';
import { writeFileSync, mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const AsyncFunction = Object.getPrototypeOf(async function () {}).constructor;
const LABEL = 'CMPLZ BANNER CSS';
let failures = 0;
const check = (name, ok, detail = '') => {
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${ok ? '' : '  ' + detail}`);
  if (!ok) failures++;
};

const dir = mkdtempSync(join(tmpdir(), 'cmplz-test-'));
function generate(css, env = {}) {
  const f = join(dir, 'banner.css');
  writeFileSync(f, css);
  return execFileSync('python3', ['scripts/apply-banner-css.py', f], {
    env: { ...process.env, CMPLZ_URL: 'https://example.test/', ...env }, encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'pipe'],
  });
}
function generateFails(css, env = {}) {
  try { generate(css, env); return false; } catch { return true; }
}

// Fake environment: one Customizer setting and a front end that reflects the published value.
async function run(js, { stored, loggedIn = true, publishes = true, changeset = '', customizeRedirect = false, loginElsewhere = false }) {
  const state = { stored, published: stored, url: '', logs: [], files: {}, filled: [] };
  const setting = { id: 'custom_css[sometheme]', get: () => state.stored, set: v => { state.stored = v; } };
  const fakeWindow = {
    wp: { customize: Object.assign(id => (id === setting.id ? setting : undefined), {
      each: fn => fn(setting), state: () => ({ get: () => changeset }), dirtyValues: () => ({}),
    }) },
  };
  const fakeDocument = {
    querySelector: sel => (sel === '#save'
      ? { disabled: true, value: 'Publish', click() { if (publishes) state.published = state.stored; this.value = 'Published'; } }
      : null),
    getElementById: id => {
      if (id !== 'wp-custom-css') return null;
      const text = state.published;
      const rules = (text.match(/[^{}]+\{[^}]*\}/g) || []).map(r => ({ cssText: r.trim() }));
      return { textContent: text, sheet: { cssRules: rules } };
    },
  };
  const page = {
    goto: async u => {
      state.url = (!loggedIn && u.includes('wp-admin')) ? (loginElsewhere ? 'http://evil.test/wp-login.php' : 'https://example.test/wp-login.php')
        : (customizeRedirect && u.includes('customize.php')) ? 'https://example.test/secret-login/' : u;
    },
    url: () => state.url,
    fill: async (sel, v) => { state.filled.push(sel); }, click: async () => { loggedIn = true; state.url = 'https://example.test/wp-admin/'; },
    waitForLoadState: async () => {}, waitForTimeout: async () => {},
    evaluate: async (fn, arg) => {
      globalThis.window = fakeWindow; globalThis.wp = fakeWindow.wp; globalThis.document = fakeDocument;
      return fn(arg);
    },
  };
  const browser = { getPage: async () => page };
  const fakeConsole = { log: (...a) => state.logs.push(a.join(' ')) };
  const writeFile = async (name, data) => { state.files[name] = data; return '/fake/tmp/' + name; };
  let error = null;
  try { await new AsyncFunction('browser', 'console', 'writeFile', js)(browser, fakeConsole, writeFile); } catch (e) { error = e; }
  return { ...state, error };
}

const count = (s, sub) => s.split(sub).length - 1;
const CSS = '.cmplz-cookiebanner .cmplz-btn{border-radius:0 !important;}';
const SITE_CSS = 'body{color:#222;}';

// 1. first run: site CSS kept, one marker block added, front end shows the rules
let r = await run(generate(CSS), { stored: SITE_CSS });
check('first run succeeds', !r.error && r.logs.some(l => l.startsWith('set: OK')), r.error?.message);
check('site CSS preserved', r.stored.startsWith(SITE_CSS));
check('exactly one marker block', count(r.stored, `${LABEL} START`) === 1 && count(r.stored, `${LABEL} END`) === 1);
check('front-end read-back reports the rules', r.logs.some(l => l.includes('"cmplzRules":1')), r.logs.join(' | '));
check('previous CSS backed up before the change', Object.values(r.files).includes(SITE_CSS), JSON.stringify(r.files));

// 2. second run with new CSS: block replaced, not duplicated
const CSS2 = '.cmplz-cookiebanner .cmplz-btn{border-radius:8px !important;}';
const r2 = await run(generate(CSS2), { stored: r.stored });
check('second run is idempotent (one block)', count(r2.stored, `${LABEL} START`) === 1, r2.stored);
check('second run replaced the CSS', r2.stored.includes('8px') && !r2.stored.includes('radius:0'));
check('site CSS still preserved', r2.stored.startsWith(SITE_CSS));

// 3. damaged marker (start without end): stop, change nothing
const damaged = `${SITE_CSS}\n/* --- ${LABEL} START --- */\n.x{}`;
const r3 = await run(generate(CSS), { stored: damaged });
check('damaged marker stops the run', !!r3.error && r3.logs.some(l => l.includes('STALE_MARKER')), r3.logs.join(' | '));
check('damaged marker leaves the value untouched', r3.stored === damaged);

// 4. not logged in and no credentials: stop before touching anything
const r4 = await run(generate(CSS), { stored: SITE_CSS, loggedIn: false });
check('not logged in without credentials stops', !!r4.error && r4.logs.some(l => l.startsWith('NOT_LOGGED_IN')));
check('not logged in leaves the value untouched', r4.stored === SITE_CSS);

// 5. not logged in with credentials: logs in and applies
const r5 = await run(generate(CSS, { CMPLZ_USER: 'u', CMPLZ_PASS: 'p' }), { stored: SITE_CSS, loggedIn: false });
check('login with credentials then apply', !r5.error && count(r5.stored, `${LABEL} START`) === 1, r5.error?.message);

// 5b. pending Customizer changes or a redirected customize.php: stop before touching anything
const r5b = await run(generate(CSS), { stored: SITE_CSS, changeset: 'draft' });
check('pending changeset stops the run', !!r5b.error && r5b.logs.some(l => l.startsWith('PENDING_CHANGES')), r5b.logs.join(' | '));
check('pending changeset leaves the value untouched', r5b.stored === SITE_CSS && Object.keys(r5b.files).length === 0);
const r5c = await run(generate(CSS), { stored: SITE_CSS, customizeRedirect: true });
check('redirected customize.php stops the run', !!r5c.error && r5c.logs.some(l => l.startsWith('NOT_LOGGED_IN')), r5c.logs.join(' | '));

// 5d. a login page outside CMPLZ_URL: credentials are never typed
const r5d = await run(generate(CSS, { CMPLZ_USER: 'u', CMPLZ_PASS: 'p' }), { stored: SITE_CSS, loggedIn: false, loginElsewhere: true });
check('login page on another origin stops the run', !!r5d.error && r5d.logs.some(l => l.startsWith('LOGIN_ORIGIN_MISMATCH')), r5d.logs.join(' | '));
check('credentials not typed on another origin', r5d.filled.length === 0);

// 6. generator refuses unsafe input
check('refuses CSS containing "<" or ">"', generateFails('.a > .b{color:red}'));
check('refuses CSS containing the marker text', generateFails(`/* ${LABEL} */ .a{}`));
check('refuses a missing CMPLZ_URL', generateFails(CSS, { CMPLZ_URL: '' }));
check('refuses http:// by default', generateFails(CSS, { CMPLZ_URL: 'http://example.test/' }));
check('allows http:// with CMPLZ_ALLOW_HTTP=1', !generateFails(CSS, { CMPLZ_URL: 'http://example.test/', CMPLZ_ALLOW_HTTP: '1' }));

// 6b. the save does not reach the front end: the run must fail, not just warn
const r8 = await run(generate(CSS), { stored: SITE_CSS, publishes: false });
check('front-end read-back failure fails the run', !!r8.error && /FRONT_CHECK_FAILED/.test(r8.error.message), r8.error?.message);

// 7. a placeholder inside a value is not substituted twice
const tricky = generate('.a::after{content:"__SITE__";}');
check('values are not rescanned for placeholders', tricky.includes('content:\\"__SITE__\\"'));

rmSync(dir, { recursive: true, force: true });
console.log(failures ? `\n${failures} check(s) FAILED` : '\nall checks passed');
process.exit(failures ? 1 : 0);
